        int mostPopularCount = colorCountMap.get(mostPopularColor);

        System.out.println("Most popular car color: " + mostPopularColor);
        System.out.println("Count: " + mostPopularCount);
    }

    static Map<String, Integer> countCarColors(List<Car> cars) {
        Map<String, Integer> colorCountMap = new HashMap<>();

        for (Car car : cars) {
            String color = car.getColor();
            if (!colorCountMap.containsKey(color)) {
                colorCountMap.put(color, 1);
            } else {
                colorCountMap.put(color, colorCountMap.get(color) + 1);
            }
        }

        return colorCountMap;
    }

    static class Car {
        private final String color;
        private final String brand;

        public Car(String color, String brand) {
            this.color = color;
            this.brand = brand;
        }

        public String getColor() {
            return color;
        }

        public String getBrand() {
            return brand;
        }
    }
}
```

In this example, the `countCarColors` method takes a `List<Car>` and returns a `Map<String, Integer>` containing the car colors and their counts. The `main` method demonstrates how to use this method to find the most popular car color and its count.

